const std = @import("std"); const mem2 = std.mem; const find = @import("pa-apiz-find.zig"); const urln = @import("ut-urlz-norm.zig"); const vali = @import("sc-reco-vali.zig");
const CF = .{ .maxl = 4000, .stkz = 64, .hidn = @as([]const []const u8, &.{ "display:none", "visibility:hidden", "opacity:0;", "opacity:0\"", "font-size:0", "width:0;", "height:0;", "width:0px", "height:0px", "left:-9999", "top:-9999", "text-indent:-9999", "position:absolute;left:-" }), .clas = @as([]const []const u8, &.{ "honeypot", "bot-trap", "hidden-link", "trap-link", "no-bot" }), .voidt = @as([]const []const u8, &.{ "br", "img", "input", "meta", "link", "hr", "area", "base", "col", "embed", "source", "track", "wbr" }) };
pub const Link = struct { urlz: []const u8, trap: bool, why2: []const u8 };
fn attrOfzz(tagz: []const u8, name: []const u8) ?[]const u8 { var buf4: [24]u8 = undefined; const patz = std.fmt.bufPrint(&buf4, "{s}=", .{name}) catch return null; var from: usize = 0; while (std.ascii.findIgnoreCasePos(tagz, from, patz)) |hitz| { from = hitz + patz.len; if (hitz == 0 or !std.ascii.isWhitespace(tagz[hitz - 1])) continue; if (from >= tagz.len) return null; const quot = tagz[from]; if (quot != '"' and quot != '\'') { var endz = from; while (endz < tagz.len and !std.ascii.isWhitespace(tagz[endz]) and tagz[endz] != '>') endz += 1; return tagz[from..endz]; } const endz = mem2.findScalarPos(u8, tagz, from + 1, quot) orelse return null; return tagz[from + 1 .. endz]; } return null; }
fn flagOfzz(tagz: []const u8, name: []const u8) bool { var from: usize = 1; while (std.ascii.findIgnoreCasePos(tagz, from, name)) |hitz| { from = hitz + name.len; const prev = tagz[hitz - 1]; const nxtz: u8 = if (hitz + name.len < tagz.len) tagz[hitz + name.len] else ' '; if (std.ascii.isWhitespace(prev) and (std.ascii.isWhitespace(nxtz) or nxtz == '>' or nxtz == '=' or nxtz == '/')) return true; } return false; }
fn hidzTagz(tagz: []const u8) ?[]const u8 { if (attrOfzz(tagz, "style")) |styz| { var lowz: [256]u8 = undefined; var lenz: usize = 0; for (styz) |chr2| { if (chr2 == ' ' or chr2 == '\t') continue; if (lenz >= lowz.len) break; lowz[lenz] = std.ascii.toLower(chr2); lenz += 1; } const cmpz = lowz[0..lenz]; var wit2: [260]u8 = undefined; @memcpy(wit2[0..lenz], cmpz); wit2[lenz] = ';'; wit2[lenz + 1] = '"'; const full = wit2[0 .. lenz + 2]; for (CF.hidn) |patz| { if (mem2.find(u8, full, patz) != null) return "hidden by style"; } } if (flagOfzz(tagz, "hidden")) return "hidden attribute"; if (attrOfzz(tagz, "aria-hidden")) |ahzz| { if (mem2.eql(u8, ahzz, "true") and (attrOfzz(tagz, "tabindex") != null)) return "aria-hidden offscreen"; } for ([_][]const u8{ "class", "id" }) |nmzz| { if (attrOfzz(tagz, nmzz)) |val2| { for (CF.clas) |patz| { if (std.ascii.findIgnoreCase(val2, patz) != null) return "honeypot name"; } } } return null; }
fn iszzVoid(name: []const u8) bool { for (CF.voidt) |vtzz| { if (std.ascii.eqlIgnoreCase(vtzz, name)) return true; } return false; }
pub fn linkFind(aren: std.mem.Allocator, base: []const u8, page: []const u8) ![]Link { const part = try urln.urlzSpli(base); const orig = try find.ori2(aren, part); var list: std.ArrayList(Link) = .empty; var stk2: [CF.stkz][]const u8 = undefined; var hidz: [CF.stkz]bool = undefined; var depz: usize = 0; var hidn: usize = 0; var kixz: usize = 0; while (kixz < page.len and list.items.len < CF.maxl) { const ltzz = mem2.findScalarPos(u8, page, kixz, '<') orelse break; const gtzz = mem2.findScalarPos(u8, page, ltzz, '>') orelse break; kixz = gtzz + 1; const tagz = page[ltzz .. gtzz + 1]; if (tagz.len < 3 or tagz[1] == '!' or tagz[1] == '?') continue; if (tagz[1] == '/') { var nmzz = tagz[2 .. tagz.len - 1]; nmzz = mem2.trim(u8, nmzz, " \t\r\n"); var jxzz = depz; while (jxzz > 0) : (jxzz -= 1) { if (std.ascii.eqlIgnoreCase(stk2[jxzz - 1], nmzz)) { while (depz >= jxzz) { depz -= 1; if (hidz[depz]) hidn -= 1; if (depz == 0) break; } break; } } continue; } var nezz: usize = 1; while (nezz < tagz.len and !std.ascii.isWhitespace(tagz[nezz]) and tagz[nezz] != '>' and tagz[nezz] != '/') nezz += 1; const name = tagz[1..nezz]; const sel2 = tagz[tagz.len - 2] == '/'; const hidr = hidzTagz(tagz); if (std.ascii.eqlIgnoreCase(name, "a")) { const href = attrOfzz(tagz, "href") orelse continue; const urlz = (find.joi2(aren, part, orig, href) catch null) orelse continue; const same = urln.urlzSpli(urlz) catch continue; if (!std.ascii.eqlIgnoreCase(same.host, part.host) or same.port != part.port) continue; var trap = false; var why2: []const u8 = "ok"; if (hidn > 0) { trap = true; why2 = "inside hidden container"; } else if (hidr) |hrzz| { trap = true; why2 = hrzz; } else if (attrOfzz(tagz, "rel")) |rlzz| { if (std.ascii.findIgnoreCase(rlzz, "nofollow") != null) { trap = true; why2 = "nofollow"; } } try list.append(aren, .{ .urlz = urlz, .trap = trap, .why2 = why2 }); continue; } if (sel2 or iszzVoid(name) or depz >= CF.stkz) continue; stk2[depz] = name; hidz[depz] = hidr != null; if (hidr != null) hidn += 1; depz += 1; } return list.toOwnedSlice(aren); }
pub fn trunChek(page: []const u8) bool { const trmz = mem2.trim(u8, page, " \t\r\n"); if (trmz.len < 20 or trmz[0] != '<') return false; if (std.ascii.findIgnoreCase(trmz, "<html") == null) return false; return std.ascii.findIgnoreCase(trmz, "</html>") == null; }
pub fn poisChek(aren: std.mem.Allocator, json: []const u8, requ: []const []const u8) !?[]const u8 { const valu = std.json.parseFromSliceLeaky(std.json.Value, aren, json, .{}) catch return "invalid json"; var obj2 = valu; if (valu == .array) { if (valu.array.items.len == 0) return "empty list"; obj2 = valu.array.items[0]; } if (obj2 != .object) return "not an object"; var recs: std.ArrayList(vali.Fiel) = .empty; for (requ) |nmzz| { const fvzz = obj2.object.get(nmzz) orelse return nmzz; const tex2: []const u8 = switch (fvzz) { .string => |sxzz| sxzz, .integer => |ind3| try std.fmt.allocPrint(aren, "{d}", .{ind3}), .float => |fxzz| try std.fmt.allocPrint(aren, "{d}", .{fxzz}), .bool => |bxzz| if (bxzz) "true" else "false", .null => "null", else => "x" }; try recs.append(aren, .{ .name = nmzz, .valu = tex2 }); } return vali.recoChek(recs.items, requ); }
